//! Regression tests for the header dictionary and CSI queries.
//!
//! `testdata/test4.bcf` was generated by bcftools from a VCF with INFO/DP and
//! FORMAT/DP, long symbolic deletions (records in large bins), a gap without
//! records (chr1:2,000,000-2,500,000) and two contigs:
//! `bcftools view -Ob -o test4.bcf test4.vcf && bcftools index -c test4.bcf`
#![allow(clippy::unwrap_used)]
use bcf_reader::*;

const HEADER: &str = concat!(
    "##fileformat=VCFv4.2\n",
    "##contig=<ID=chr1,length=5000000>\n",
    "##contig=<ID=chr2,length=1000000>\n",
    "##ALT=<ID=DEL,Description=\"Deletion\">\n",
    "##INFO=<ID=DP,Number=1,Type=Integer,Description=\"Total Depth\">\n",
    "##INFO=<ID=END,Number=1,Type=Integer,Description=\"End position\">\n",
    "##FORMAT=<ID=GT,Number=1,Type=String,Description=\"Genotype\">\n",
    "##FORMAT=<ID=DP,Number=1,Type=Integer,Description=\"Read Depth\">\n",
    "##FORMAT=<ID=AD,Number=R,Type=Integer,Description=\"Allelic depths\">\n",
    "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tS1\tS2\n",
);

fn check_keys(header: &Header) {
    // as htslib: PASS=0, DP=1 (shared by INFO and FORMAT), END=2, GT=3, AD=4
    let key = |d, id| header.get_idx_from_dictionary_str(d, id);
    assert_eq!(key("FILTER", "PASS"), Some(0));
    assert_eq!(key("INFO", "DP"), Some(1));
    assert_eq!(key("FORMAT", "DP"), Some(1));
    assert_eq!(key("INFO", "END"), Some(2));
    assert_eq!(key("FORMAT", "GT"), Some(3));
    assert_eq!(header.get_fmt_gt_id(), Some(3));
    assert_eq!(key("FORMAT", "AD"), Some(4));
    assert_eq!(key("INFO", "GT"), None);
    assert_eq!(header.dict_strings().len(), 5);
    assert_eq!(header.dict_strings()[&1]["Dictionary"], "INFO");
    assert_eq!(
        header.get_dictionary_attrs("FORMAT", "DP").unwrap()["Description"],
        "Read Depth"
    );
    assert_eq!(header.get_chrname(1), "chr2");
}

#[test]
fn shared_ids_without_idx() {
    check_keys(&Header::from_string(HEADER).unwrap());
}

#[test]
fn shared_ids_with_idx() {
    // bcftools writes IDX attributes into BCF headers
    let mut f = smart_reader("testdata/test4.bcf").unwrap();
    let text = read_header(&mut f).unwrap();
    assert!(
        text.contains("##FORMAT=<ID=DP,Number=1,Type=Integer,Description=\"Read Depth\",IDX=1>")
    );
    let header = Header::from_string(&text).unwrap();
    check_keys(&header);

    // FORMAT/DP values are read with the shared key
    let mut record = Record::default();
    record.read(&mut f).unwrap();
    let dp: Vec<_> = record
        .fmt_field(header.get_idx_from_dictionary_str("FORMAT", "DP").unwrap())
        .map(|v| v.unwrap().int_val().unwrap())
        .collect();
    assert_eq!(dp.len(), 2);
    assert_eq!(dp[1], dp[0] + 1);
}

#[test]
fn conflicting_idx_is_an_error() {
    let text = HEADER.replace(
        "##INFO=<ID=END,Number=1,Type=Integer,Description=\"End position\">",
        "##INFO=<ID=END,Number=1,Type=Integer,Description=\"End position\",IDX=1>",
    );
    assert!(Header::from_string(&text).is_err());
}

#[test]
fn csi_bins() {
    let csi = Csi::from_path("testdata/test4.bcf.csi").unwrap();
    // 5 Mb contigs: min_shift 14, depth 3 (16 kb * 8^3 = 8 Mb); bins of
    // 8 Mb (0), 1 Mb (1-8), 128 kb (9-72) and 16 kb (73-584)
    assert_eq!(csi.get_bin_limit(), 585);
    assert_eq!(csi.get_bin_id(0, 1), 73);
    assert_eq!(csi.get_bin_id(16384, 16385), 74);
    // ranges spanning several leaf bins
    assert_eq!(csi.get_bin_id(16383, 16385), 9);
    assert_eq!(csi.get_bin_id(1 << 20, 1 << 21), 2);
    assert_eq!(csi.get_bin_id(0, 1 << 22), 0);
    assert_eq!(csi.get_bin_ids(0, 1), vec![0, 1, 9, 73]);
    assert_eq!(csi.get_bin_ids(16383, 16385), vec![0, 1, 9, 73, 74]);
}

/// (chrom, pos) of all records, read sequentially
fn all_positions() -> Vec<(usize, i64)> {
    let mut reader = BcfReader::from_reader(smart_reader("testdata/test4.bcf").unwrap());
    reader.read_header().unwrap();
    let mut record = Record::default();
    let mut out = vec![];
    while reader.read_record(&mut record).is_ok() {
        out.push((record.chrom() as usize, record.pos() as i64));
    }
    out
}

#[test]
fn interval_queries_match_a_full_scan() {
    let all = all_positions();
    assert_eq!(all.len(), 10457);
    let mut reader =
        IndexedBcfReader::from_path("testdata/test4.bcf", "testdata/test4.bcf.csi", None).unwrap();
    reader.read_header().unwrap();
    let mut record = Record::default();

    let mut intervals = vec![
        (0, 0, Some(1)),
        (0, 0, Some(100_000)),
        (0, 2_100_000, Some(2_400_000)), // no record in the gap
        (0, 2_300_000, Some(2_600_000)), // starts in the gap
        (0, 4_700_000, None),            // must not run into chr2
        (1, 0, None),
        (1, 899_000, Some(2_000_000)),
        (0, 4_900_000, Some(5_000_000)), // after the last record of chr1
    ];
    let mut x: u64 = 12345;
    for _ in 0..200 {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        let chrom = (x % 2) as usize;
        let start = ((x >> 8) % 5_000_000) as i64;
        let width = [1, 1_000, 20_000, 300_000][(x >> 40) as usize % 4];
        intervals.push((chrom, start, Some(start + width)));
    }

    let mut total = 0;
    for (chrom_id, start, end) in intervals {
        let expected: Vec<i64> = all
            .iter()
            .filter(|(c, p)| *c == chrom_id && *p >= start && end.is_none_or(|e| *p < e))
            .map(|(_, p)| *p)
            .collect();
        reader
            .set_interval(GenomeInterval {
                chrom_id,
                start,
                end,
            })
            .unwrap();
        let mut found = vec![];
        while reader.read_record(&mut record).is_ok() {
            found.push(record.pos() as i64);
        }
        assert_eq!(found, expected, "interval {chrom_id}:{start}-{end:?}");
        total += found.len();
    }
    assert!(total > 1000);
}
